    try {
        tracker.postComment(ticketKey, postHelpers.buildPrFailureComment(branchName, prResult.error));
        tracker.moveToStatus(ticketKey, jiraConfig.statuses.BACKLOG);
    } catch (e) { console.warn('Could not reset to Backlog:', e); }
    try {
