                var branchMissing = cleanCommandOutput(rawBranchMissing);
                if (branchMissing) {
                    runInRepo('git config user.name "' + config.git.authorName + '"', workingDir);
                    runInRepo('git config user.email "' + config.git.authorEmail + '"', workingDir);
