            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            status: result.status,
            ticketKey: ticketKey,
            prUrl: prUrl
        };

    } catch (error) {
        console.error('❌ Error in postTestAutomationResults:', error);
        try {
            tracker.postComment(params.ticket.key, postHelpers.buildErrorComment(error));
        } catch (e) {}
        try {
