            if (smTriggerLabel) {
                tracker.removeLabel(params.ticket.key, smTriggerLabel);
                console.log('✅ Removed SM trigger label on error:', smTriggerLabel);
            }
        } catch (e) {}
        return { success: false, error: error.toString() };
    }
