            console.log('✅ Removed SM trigger label on PR failure:', smTriggerLabel);
        }
    } catch (e) { console.warn('Could not remove SM trigger label:', e); }
    return { success: false, error: 'PR creation failed: ' + (prResult.error || 'no URL returned') };
}

